const NAVIGATION_TIMEOUT_MS = 4000;

// Rest (Musik, Klänge, Bilder): je Datei einzeln und fehlertolerant, was schon gespeichert ist, wird übersprungen.
// Ein Fehlschlag bleibt folgenlos (kein Wurf, keine Blockade) und wird beim nächsten Start des Service Workers erneut
// versucht. Das Versprechen gilt je Worker-Lauf, damit viele Abrufe nicht dieselben Dateien mehrfach anstoßen.
let restRun = null;
function fillRest() {
  if (!restRun) {
    restRun = Promise.resolve().then(() => caches.open(VERSION)).then(async (cache) => {
      for (const f of REST) {
        try {
          if (!(await cache.match(BASE + f))) await cache.add(BASE + f);
        } catch (e) {
          // Wird beim nächsten Mal erneut versucht; bis dahin holt der Abruf-Handler die Datei bei Gebrauch.
        }
      }
    }).catch(() => undefined);
  }
  return restRun;
}

self.addEventListener('install', (event) => {
  // Nur der Kern wird atomar gespeichert (D-107): scheitert er, scheitert die Installation. Der Rest kommt nie hier hinein.
  event.waitUntil(
    caches
      .open(VERSION)
      .then((cache) => cache.addAll(CORE.map((f) => BASE + f)))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()),
  );
  // Rest im Hintergrund, ohne die Aktivierung aufzuhalten; hält der Browser den Worker nicht lange genug am Leben,
  // setzt der erste Abruf danach (siehe unten) die Arbeit fort.
  fillRest();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  // Hält den Worker für die Rest-Downloads am Leben und stößt sie nach einem Abbruch oder Fehler erneut an.
  event.waitUntil(fillRest());
  if (request.mode === 'navigate') {
    // Seiten: neuester Stand aus dem Netz. Ohne Netz, bei einem Fehler des Servers (GitHub Pages antwortet auf
    // Unterseiten mit 404) oder wenn das Netz nach NAVIGATION_TIMEOUT_MS nichts liefert (verbunden, aber tot), die
    // gespeicherte App; die App wählt die Seite dann selbst. Die Netzantwort läuft im Hintergrund zu Ende.
    const cached = () => caches.match(BASE);
    const network = fetch(request);
    event.waitUntil(network.catch(() => undefined));
    const first = Promise.race([
      network.catch(() => null),
      new Promise((resolve) => setTimeout(() => resolve(null), NAVIGATION_TIMEOUT_MS)),
    ]);
    event.respondWith(
      first.then((response) => {
        if (response && response.ok) return response;
        return cached().then((hit) => hit || response || network);
      }),
    );
    return;
  }
  event.respondWith(
    caches.match(request, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(request).then((response) => {
          // Teilantwort (Browser fordern Audio stückweise an): lässt sich nicht speichern. Die ganze Datei einmal im
          // Hintergrund holen, damit die Musik danach auch offline läuft.
          if (response.status === 206) {
            event.waitUntil(
              caches
                .open(VERSION)
                .then((cache) => cache.match(request.url).then((have) => have || cache.add(request.url)))
                .catch(() => undefined),
            );
            return response;
          }
          if (response.ok) {
            const copy = response.clone();
            caches.open(VERSION).then((cache) => cache.put(request, copy));
          }
          return response;
        }),
    ),
  );
});
